int main(int argc, char** argv) {
    printf("=== %s [PhasorLang Native AOT] ===\n", "MiJuegoPhasor");
    int pc = 0;
    int codeLen = 3764;
    while (pc < codeLen) {
        uint32_t inst = BYTECODE[pc++];
        uint8_t op   = (inst >> 24) & 0xFF;
        uint8_t rDst = (inst >> 16) & 0xFF;
        uint8_t rS1  = (inst >> 8)  & 0xFF;
        uint8_t rS2  = inst & 0xFF;
        if (op == 0xFF) break; // HALT
        switch (op) {
            case 0x01: rScalar[rDst] = CONST_POOL[rS1]; isVec[rDst]=false; break;
            case 0x02: rScalar[rDst] = rScalar[rS1]; break;
            case 0x10: rScalar[rDst] = rScalar[rS1] + rScalar[rS2]; break;
            case 0x11: rScalar[rDst] = rScalar[rS1] - rScalar[rS2]; break;
            case 0x12: rScalar[rDst] = rScalar[rS1] * rScalar[rS2]; break;
            case 0x13: rScalar[rDst] = rScalar[rS1] / rScalar[rS2]; break;
            case 0x60: {
                uint8_t rZ = (BYTECODE[pc++] >> 8) & 0xFF;
                rVecX[rDst] = rScalar[rS1]; rVecY[rDst] = rScalar[rS2]; rVecZ[rDst] = rScalar[rZ];
                isVec[rDst] = true; break;
            }
            case 0x61: {
                rVecX[rDst] = rVecX[rS1] + rVecX[rS2];
                rVecY[rDst] = rVecY[rS1] + rVecY[rS2];
                rVecZ[rDst] = rVecZ[rS1] + rVecZ[rS2];
                isVec[rDst] = true; break;
            }
            case 0x64: {
                rScalar[rDst] = rVecX[rS1]*rVecX[rS2] + rVecY[rS1]*rVecY[rS2] + rVecZ[rS1]*rVecZ[rS2];
                isVec[rDst] = false; break;
            }
            case 0x30: {
                if (isVec[rS1]) printf("> OUT: [%.4f, %.4f, %.4f]\n", rVecX[rS1], rVecY[rS1], rVecZ[rS1]);
                else printf("> OUT: %.4f\n", rScalar[rS1]);
                break;
            }
        }
    }
    printf("> Ejecucion AOT Nativa Finalizada con Exito.\n");
    return 0;
}
